//! The Vulkan FFI structures and constants against the C compiler's view of `vulkan.h` (Vulkan
//! 1.4.363): sizes, alignments, field offsets and the numbers of the structures the import probe
//! uses. Generated by running a C program (GCC against the Vulkan headers, x86-64 Linux) that
//! prints `sizeof` / `offsetof` of them; the header itself is not in this repository.
#![allow(clippy::unreadable_literal)]

use super::ffi::*;
use std::mem::{align_of, offset_of, size_of};

#[test]
fn layouts_match_the_header() {
    assert_eq!((size_of::<VkApplicationInfo>(), align_of::<VkApplicationInfo>()), (48, 8), "VkApplicationInfo");
    assert_eq!(offset_of!(VkApplicationInfo, s_type), 0, "VkApplicationInfo.sType");
    assert_eq!(offset_of!(VkApplicationInfo, p_next), 8, "VkApplicationInfo.pNext");
    assert_eq!(offset_of!(VkApplicationInfo, p_application_name), 16, "VkApplicationInfo.pApplicationName");
    assert_eq!(offset_of!(VkApplicationInfo, application_version), 24, "VkApplicationInfo.applicationVersion");
    assert_eq!(offset_of!(VkApplicationInfo, p_engine_name), 32, "VkApplicationInfo.pEngineName");
    assert_eq!(offset_of!(VkApplicationInfo, engine_version), 40, "VkApplicationInfo.engineVersion");
    assert_eq!(offset_of!(VkApplicationInfo, api_version), 44, "VkApplicationInfo.apiVersion");
    assert_eq!((size_of::<VkInstanceCreateInfo>(), align_of::<VkInstanceCreateInfo>()), (64, 8), "VkInstanceCreateInfo");
    assert_eq!(offset_of!(VkInstanceCreateInfo, s_type), 0, "VkInstanceCreateInfo.sType");
    assert_eq!(offset_of!(VkInstanceCreateInfo, p_next), 8, "VkInstanceCreateInfo.pNext");
    assert_eq!(offset_of!(VkInstanceCreateInfo, flags), 16, "VkInstanceCreateInfo.flags");
    assert_eq!(offset_of!(VkInstanceCreateInfo, p_application_info), 24, "VkInstanceCreateInfo.pApplicationInfo");
    assert_eq!(offset_of!(VkInstanceCreateInfo, enabled_layer_count), 32, "VkInstanceCreateInfo.enabledLayerCount");
    assert_eq!(offset_of!(VkInstanceCreateInfo, pp_enabled_layer_names), 40, "VkInstanceCreateInfo.ppEnabledLayerNames");
    assert_eq!(offset_of!(VkInstanceCreateInfo, enabled_extension_count), 48, "VkInstanceCreateInfo.enabledExtensionCount");
    assert_eq!(offset_of!(VkInstanceCreateInfo, pp_enabled_extension_names), 56, "VkInstanceCreateInfo.ppEnabledExtensionNames");
    assert_eq!((size_of::<VkPhysicalDeviceProperties>(), align_of::<VkPhysicalDeviceProperties>()), (824, 8), "VkPhysicalDeviceProperties");
    assert_eq!(offset_of!(VkPhysicalDeviceProperties, api_version), 0, "VkPhysicalDeviceProperties.apiVersion");
    assert_eq!(offset_of!(VkPhysicalDeviceProperties, driver_version), 4, "VkPhysicalDeviceProperties.driverVersion");
    assert_eq!(offset_of!(VkPhysicalDeviceProperties, vendor_id), 8, "VkPhysicalDeviceProperties.vendorID");
    assert_eq!(offset_of!(VkPhysicalDeviceProperties, device_id), 12, "VkPhysicalDeviceProperties.deviceID");
    assert_eq!(offset_of!(VkPhysicalDeviceProperties, device_type), 16, "VkPhysicalDeviceProperties.deviceType");
    assert_eq!(offset_of!(VkPhysicalDeviceProperties, device_name), 20, "VkPhysicalDeviceProperties.deviceName");
    assert_eq!((size_of::<VkPhysicalDeviceProperties2>(), align_of::<VkPhysicalDeviceProperties2>()), (840, 8), "VkPhysicalDeviceProperties2");
    assert_eq!(offset_of!(VkPhysicalDeviceProperties2, s_type), 0, "VkPhysicalDeviceProperties2.sType");
    assert_eq!(offset_of!(VkPhysicalDeviceProperties2, p_next), 8, "VkPhysicalDeviceProperties2.pNext");
    assert_eq!(offset_of!(VkPhysicalDeviceProperties2, properties), 16, "VkPhysicalDeviceProperties2.properties");
    assert_eq!((size_of::<VkPhysicalDeviceDrmPropertiesEXT>(), align_of::<VkPhysicalDeviceDrmPropertiesEXT>()), (56, 8), "VkPhysicalDeviceDrmPropertiesEXT");
    assert_eq!(offset_of!(VkPhysicalDeviceDrmPropertiesEXT, s_type), 0, "drm.sType");
    assert_eq!(offset_of!(VkPhysicalDeviceDrmPropertiesEXT, p_next), 8, "drm.pNext");
    assert_eq!(offset_of!(VkPhysicalDeviceDrmPropertiesEXT, has_primary), 16, "drm.hasPrimary");
    assert_eq!(offset_of!(VkPhysicalDeviceDrmPropertiesEXT, has_render), 20, "drm.hasRender");
    assert_eq!(offset_of!(VkPhysicalDeviceDrmPropertiesEXT, primary_major), 24, "drm.primaryMajor");
    assert_eq!(offset_of!(VkPhysicalDeviceDrmPropertiesEXT, primary_minor), 32, "drm.primaryMinor");
    assert_eq!(offset_of!(VkPhysicalDeviceDrmPropertiesEXT, render_major), 40, "drm.renderMajor");
    assert_eq!(offset_of!(VkPhysicalDeviceDrmPropertiesEXT, render_minor), 48, "drm.renderMinor");
    assert_eq!(size_of::<VkExtensionProperties>(), 260, "VkExtensionProperties");
    assert_eq!(offset_of!(VkExtensionProperties, extension_name), 0, "VkExtensionProperties.extensionName");
    assert_eq!(offset_of!(VkExtensionProperties, spec_version), 256, "VkExtensionProperties.specVersion");
    assert_eq!(VK_MAX_EXTENSION_NAME_SIZE, 256, "VK_MAX_EXTENSION_NAME_SIZE");
}

#[test]
fn constants_match_the_header() {
    assert_eq!(VK_SUCCESS, 0, "VK_SUCCESS");
    assert_eq!(VK_INCOMPLETE, 5, "VK_INCOMPLETE");
    assert_eq!(VK_STRUCTURE_TYPE_APPLICATION_INFO, 0, "VK_STRUCTURE_TYPE_APPLICATION_INFO");
    assert_eq!(VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO, 1, "VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO");
    assert_eq!(VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2, 1000059001, "VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2");
    assert_eq!(VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_DRM_PROPERTIES_EXT, 1000353000, "VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_DRM_PROPERTIES_EXT");
    assert_eq!(VK_API_VERSION_1_1, 0x00401000, "VK_MAKE_API_VERSION(0, 1, 1, 0)");
    assert_eq!(version_major(VK_API_VERSION_1_1), 1, "VK_VERSION_MAJOR");
    assert_eq!(version_minor(VK_API_VERSION_1_1), 1, "VK_VERSION_MINOR");
}
